package com.mo.economy_system.common.market;
import java.util.*;
public record ConfirmDemandOrderOutcome(ConfirmDemandOrderResult result,Optional<MarketOrder> confirmedOrder,boolean marketChanged){public ConfirmDemandOrderOutcome{Objects.requireNonNull(result);Objects.requireNonNull(confirmedOrder);if(result==ConfirmDemandOrderResult.SUCCESS&&(confirmedOrder.isEmpty()||!marketChanged))throw new IllegalArgumentException("success requires order and market change");}public static ConfirmDemandOrderOutcome failure(ConfirmDemandOrderResult r){return new ConfirmDemandOrderOutcome(r,Optional.empty(),false);}public static ConfirmDemandOrderOutcome afterRemoval(ConfirmDemandOrderResult r,MarketOrder o,boolean c){return new ConfirmDemandOrderOutcome(r,Optional.of(o),c);}public static ConfirmDemandOrderOutcome success(MarketOrder o){return afterRemoval(ConfirmDemandOrderResult.SUCCESS,o,true);}}
